\begin{ex}%[9H5V3-8]
\immini[thm]{
Một dây curoa ôm sát ròng rọc tâm $O$ bán kính $R = 6\,\text{cm}$; hai nhánh thẳng tiếp xúc tại $A, B$ kéo căng cắt nhau tại $M$ sao cho $\widehat{AMB} = 60^\circ$ (như hình vẽ). Xét tính đúng sai của các khẳng định sau:
\choiceTF
{\True Tam giác $OAM$ vuông tại $A$ và $\widehat{AMO} = 30^\circ$}
  {Độ dài đoạn dây thẳng $MA = 12\,\text{cm}$}
  {\True Số đo cung lớn $AB$ dây curoa ôm lấy ròng rọc là $240^\circ$}
  {\True Lấy $\pi \approx 3{,}14$, tổng chiều dài dây curoa làm tròn đến hàng phần mười là $45{,}9\,\text{cm}$}
}{
\begin{tikzpicture}[line cap=round, line join=round, >=stealth, font=\scriptsize, scale=0.52]
\def\R{2.3}
\pgfmathsetmacro{\visHalfA}{27}
\pgfmathsetmacro{\OMx}{\R/sin(\visHalfA)}
\pgfmathsetmacro{\phi}{90-\visHalfA}
\coordinate (O) at (0,0);
\coordinate (M) at (\OMx,0);
\coordinate (A) at (\phi:\R);
\coordinate (B) at (-\phi:\R);
\filldraw[fill=gray!75, draw=black, thick] (-0.36,3.1) -- (-0.36,0) arc (180:360:0.36) -- (0.36,3.1) -- cycle;
\filldraw[fill=black!55, draw=black, thick] (O) circle (\R);
\filldraw[fill=gray!30, draw=black, thick] (O) circle (\R*0.42);
\filldraw[fill=white, draw=black, thick] (O) circle (0.14);
\draw[line width=3.2pt, orange!90!black] (M) -- (A) arc (\phi:{360-\phi}:\R) -- cycle;
\draw[line width=1.3pt, yellow!90!orange] (M) -- (A) arc (\phi:{360-\phi}:\R) -- cycle;
\draw[dashed, thick, blue!80!black] (O) -- (M) (O) -- (A) node[pos=0.68, above left=0pt] {$R=6$} (O) -- (B);
\draw[red!80!black, thick] ($(M)+({180-\visHalfA}:0.85)$) arc ({180-\visHalfA}:{180+\visHalfA}:0.85);
\node[left, red!80!black, fill=white, inner sep=0.8pt] at ($(M)+(-0.98,0)$) {$60^\circ$};
\fill (O) circle (1.8pt) node[below left] {$O$};
\fill (M) circle (1.8pt) node[right] {$M$};
\fill (A) circle (1.8pt) node[above] {$A$};
\fill (B) circle (1.8pt) node[below] {$B$};
\end{tikzpicture}
}
