\begin{itemchoice}
\itemch Theo tính chất hai tiếp tuyến cắt nhau, $MO$ là phân giác $\widehat{AMB}$ nên $\widehat{AMO} = 30^\circ$.
\itemch $MA = OA \cdot \cot 30^\circ = 6 \cdot \sqrt{3} = 6\sqrt{3}\,\text{cm}$.
\itemch Trong tứ giác $OAMB$, $\widehat{AOB}_{\text{nhỏ}} = 180^\circ - 60^\circ = 120^\circ$, nên cung lớn có số đo $360^\circ - 120^\circ = 240^\circ$.
\itemch $L = 2MA + \dfrac{240}{180}\pi R \approx 45{,}9\,\text{cm}$.
\end{itemchoice}
